contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        uint preContractBalance = address(c).balance;
        uint preCallerBalance = address(this).balance;
        uint preDepositsCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        address preOwner = c.owner(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(_value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint postContractBalance = address(c).balance;
        uint postCallerBalance = address(this).balance;
        uint postDepositsCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        address postOwner = c.owner(); if (__ESBMC_reverted()) return;

        assert(
            (reverted == (_value > preContractBalance)) &&
            (reverted || (postContractBalance == preContractBalance - _value && postCallerBalance == preCallerBalance + _value)) &&
            (postDepositsCount == preDepositsCount) &&
            (postOwner == preOwner)
        );
    }

    receive() external payable {}
}

